import java.util.*;

class Solution {
    public int minHops(int[] stones) {
        int hops = 0, windowEnd = 0, farthest = 0;
        for (int i = 0; i < stones.length - 1; i++) {
            farthest = Math.max(farthest, i + stones[i]);   // best reach from this window
            if (i == windowEnd) {                            // window used up: hop
                hops++;
                windowEnd = farthest;
            }
        }
        return hops;
    }
}

